<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php';Auth::requireLogin();$db=Database::getInstance()->pdo();if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::verify($_POST['csrf_token']??'');$id=(int)$_POST['customer_id'];$amount=abs((float)$_POST['amount']);$type=$_POST['type'];$allowed=array('debt_payment','deposit','adjustment');if(!$id||$amount<=0||!in_array($type,$allowed,true)){Helper::flash('تأكد من صحة البيانات.','danger');Helper::redirect('modules/payments/index.php');}$db->beginTransaction();try{$st=$db->prepare('SELECT balance FROM customers WHERE id=? FOR UPDATE');$st->execute(array($id));$balance=$st->fetchColumn();if($balance===false)throw new Exception('الزبون غير موجود');$delta=$type==='debt_payment'?$amount:($type==='deposit'?$amount:(isset($_POST['direction'])&&$_POST['direction']==='minus'?-$amount:$amount));$after=(float)$balance+$delta;$db->prepare('UPDATE customers SET balance=? WHERE id=?')->execute(array($after,$id));$db->prepare('INSERT INTO payments(customer_id,user_id,type,amount,balance_after,note,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute(array($id,Auth::user()['id'],$type,$delta,$after,trim($_POST['note'])));$db->commit();Helper::flash('تم تسجيل الحركة بنجاح.','success');}catch(Exception $e){$db->rollBack();Helper::flash($e->getMessage(),'danger');}Helper::redirect('modules/payments/index.php');}$customers=$db->query('SELECT id,name,balance FROM customers ORDER BY name')->fetchAll();$rows=$db->query('SELECT p.*,c.name customer,u.full_name FROM payments p JOIN customers c ON c.id=p.customer_id JOIN users u ON u.id=p.user_id ORDER BY p.id DESC LIMIT 100')->fetchAll();$pageTitle='الديون والإيداعات';require APP_ROOT.'/includes/header.php';?><div class="page-heading"><div><h1>الديون والإيداعات</h1><p>تسديد دين، تسجيل إيداع، أو تعديل الرصيد</p></div></div><div class="card mb-3"><div class="card-header">تسجيل حركة مالية للزبون</div><div class="card-body"><form method="post" class="row g-3 align-items-end"><?= Helper::csrfField() ?><div class="col-md-3"><label class="form-label">الزبون</label><select class="form-select" name="customer_id" required><option value="">اختر</option><?php foreach($customers as $c): ?><option value="<?= (int)$c['id'] ?>"><?= Helper::e($c['name']) ?> (<?= Helper::money($c['balance']) ?>)</option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">نوع الحركة</label><select class="form-select" name="type" id="payType"><option value="debt_payment">تسديد دين</option><option value="deposit">إيداع مسبق</option><option value="adjustment">تعديل رصيد</option></select></div><div class="col-md-2"><label class="form-label">المبلغ</label><input class="form-control" type="number" name="amount" min="0.01" step="0.01" required></div><div class="col-md-2" id="directionWrap" style="display:none"><label class="form-label">الاتجاه</label><select class="form-select" name="direction"><option value="plus">زيادة</option><option value="minus">خصم</option></select></div><div class="col-md-2"><label class="form-label">ملاحظة</label><input class="form-control" name="note"></div><div class="col-md-1"><button class="btn btn-coffee w-100">حفظ</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>التاريخ</th><th>الزبون</th><th>النوع</th><th>المبلغ (+ يزيد الرصيد)</th><th>الرصيد بعد الحركة</th><th>الموظف</th><th>ملاحظة</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= Helper::e($r['created_at']) ?></td><td><?= Helper::e($r['customer']) ?></td><td><?= Helper::e($r['type']) ?></td><td><?= Helper::money($r['amount']) ?></td><td><?= Helper::money($r['balance_after']) ?></td><td><?= Helper::e($r['full_name']) ?></td><td><?= Helper::e($r['note']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><script>document.getElementById('payType').onchange=function(){document.getElementById('directionWrap').style.display=this.value==='adjustment'?'block':'none'};</script><?php require APP_ROOT.'/includes/footer.php';
